module matrix_recovery (\n    input clk, rst_n, start,\n    input [3:0] n, m,\n    input [7:0] row_parity,\n    input [7:0] col_parity,\n    output reg [7:0] matrix_out [0:7],\n    output reg done,\n    output reg error\n);\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] CHECK = 3'd1;\n    localparam [2:0] INITIALIZE = 3'd2;\n    localparam [2:0] FIX_PARITY = 3'd3;\n    localparam [2:0] DONE_STATE = 3'd4;\n    localparam [2:0] ERROR_STATE = 3'd5;\n    \n    reg [2:0] state, next_state;\n    reg [3:0] row_idx, col_idx;\n    reg [7:0] matrix [0:7];\n    reg [7:0] row_parity_check;\n    reg [7:0] col_parity_check;\n    reg [3:0] cycle_counter;\n    localparam [3:0] MAX_CYCLES = 4'd100;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            error <= 1'b0;\n            row_idx <= 4'd0;\n            col_idx <= 4'd0;\n            cycle_counter <= 4'd0;\n            for (integer k=0; k<8; k=k+1) begin\n                matrix[k] <= 8'd0;\n                matrix_out[k] <= 8'd0;\n            end\n            row_parity_check <= 8'd0;\n            col_parity_check <= 8'd0;\n        end else begin\n            state <= next_state;\n            cycle_counter <= (state == IDLE) ? 4'd0 : cycle_counter + 4'd1;\n            \n            case (state)\n                CHECK: begin\n                    row_parity_check <= 8'd0;\n                    col_parity_check <= 8'd0;\n                end\n                \n                INITIALIZE: begin\n                    if (row_idx < n) begin\n                        if (col_idx < m) begin\n                            matrix[row_idx][col_idx] <= 1'b1;\n                            col_idx <= col_idx + 4'd1;\n                        end else begin\n                            row_idx <= row_idx + 4'd1;\n                            col_idx <= 4'd0;\n                        end\n                    end\n                end\n                \n                FIX_PARITY: begin\n                    if ((row_parity_check != row_parity || col_parity_check != col_parity) && cycle_counter < MAX_CYCLES) begin\n                        for (integer i=0; i<8; i=i+1) begin\n                            for (integer j=0; j<8; j=j+1) begin\n                                if (i < n && j < m && row_parity_check[i] != row_parity[i] && col_parity_check[j] != col_parity[j] && matrix[i][j]) begin\n                                    matrix[i][j] <= 1'b0;\n                                    row_parity_check[i] <= ~row_parity_check[i];\n                                    col_parity_check[j] <= ~col_parity_check[j];\n                                end\n                            end\n                        end\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    for (integer k=0; k<8; k=k+1)\n                        matrix_out[k] <= (k < n) ? matrix[k] : 8'd0;\n                end\n                \n                ERROR_STATE: begin\n                    done <= 1'b1;\n                    error <= 1'b1;\n                    for (integer k=0; k<8; k=k+1)\n                        matrix_out[k] <= 8'd0;\n                end\n            endcase\n        end\n    end\n\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: next_state = start ? CHECK : IDLE;\n            \n            CHECK: begin\n                if (^row_parity != ^col_parity) next_state = ERROR_STATE;\n                else if (cycle_counter > 4'd1) next_state = INITIALIZE;\n            end\n            \n            INITIALIZE: begin\n                if (row_idx >= n) begin\n                    next_state = FIX_PARITY;\n                end else if (cycle_counter > MAX_CYCLES) begin\n                    next_state = ERROR_STATE;\n                end\n            end\n            \n            FIX_PARITY: begin\n                if (row_parity_check == row_parity && col_parity_check == col_parity) begin\n                    next_state = DONE_STATE;\n                end else if (cycle_counter >= MAX_CYCLES) begin\n                    next_state = ERROR_STATE;\n                end\n            end\n            \n            DONE_STATE, ERROR_STATE: next_state = IDLE;\n            \n            default: next_state = IDLE;\n        endcase\n    end\nendmodule